const { createHmac, timingSafeEqual } = require('crypto');
const item = $input.first();
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const secret = $env.N8N_ESCALATION_WEBHOOK_SECRET;
const signature = item.json.headers['x-armans-signature'];
if (!secret || typeof signature !== 'string' || !/^[a-f0-9]{64}$/i.test(signature)) {
  throw new Error('Invalid escalation signature');
}
const expected = createHmac('sha256', secret).update(raw).digest();
if (!timingSafeEqual(expected, Buffer.from(signature, 'hex'))) {
  throw new Error('Invalid escalation signature');
}
const payload = JSON.parse(raw.toString('utf8'));
if (!['abstained', 'escalated'].includes(payload.event) ||
    !['ticket_id', 'tenant', 'queue', 'reason', 'timestamp'].every((key) => typeof payload[key] === 'string' && payload[key])) {
  throw new Error('Invalid escalation payload');
}
const key = payload.ticket_id + ':' + payload.event;
if (item.json.headers['idempotency-key'] !== key) throw new Error('Invalid idempotency key');
return [{ json: { key, encodedPayload: raw.toString('base64') } }];

