WITH new_alert AS (
  INSERT INTO escalation_alerts (idempotency_key, payload)
  VALUES ($1, convert_from(decode($2, 'base64'), 'UTF8')::jsonb)
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING idempotency_key
), alert_signal AS (
  SELECT pg_notify('armans_escalation', idempotency_key) FROM new_alert
)
SELECT EXISTS (SELECT 1 FROM alert_signal) AS queued;
